// The spreadsheet projection of data/providers.json: scalar fields only, generated by scripts/build.mjs.
// Nested objects and arrays stay in JSON; unknown and null stay empty here, never false or 0.

export const PROVIDER_CSV_COLUMNS = [
  'dataset_version',
  'dataset_generated',
  'slug',
  'name',
  'category',
  'free_type',
  'free_tier',
  'rate_limits',
  'notes',
  'best_for',
  'expires',
  'docs_url',
  'models_url',
  'phone_required',
  'card_required',
  'commercial_ok',
  'commercial_ok_condition',
  'openai_compatible',
  'openai_base_url',
  'is_text_llm',
  'model_tier',
  'verified',
  'last_verified',
  'added',
  'last_probed',
  'probe_status',
];

export const PROVIDER_CSV_OMITTED = [
  'modalities',
  'models_free',
  'model_tier_source',
  'free_limits',
  'no_expiry',
  'data_policy',
  'env_key',
];

const cell = (value) => {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'string' && /^\s*[=+@-]/.test(value) ? `'${value}` : String(value);
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};

/** @param {{version: string, generated: string, providers: object[]}} data publicProviders: env_key already stripped */
export function providersCsv(data) {
  const rows = data.providers.map((p) => PROVIDER_CSV_COLUMNS.map((name) => {
    if (name === 'dataset_version') return cell(data.version);
    if (name === 'dataset_generated') return cell(data.generated);
    return cell(p[name]);
  }));
  return [PROVIDER_CSV_COLUMNS.map(cell).join(','), ...rows.map((r) => r.join(','))].join('\n') + '\n';
}
